const OVAL = [[64, -425], [52, -406], [16, -371], [-12, -312], [-30, -253], [-28, -201], [0, -189], [30, -184], [45, -199], [68, -254], [74, -331], [58, -407]];

// ---------- ground ----------
const LAKE = (() => { const o = []; for (let i = 0; i < 28; i++){ const a = i/28*TAU; o.push([-575 + Math.cos(a)*150 + Math.sin(2*a)*12, 560 + Math.sin(a)*175]); } return o; })();
const ARBOR = [[180, -800], [290, -680], [470, -470], [520, -580], [548, -680], [565, -860], [520, -985], [380, -1080], [205, -1080], [150, -840]];
