    ROADS = STF_ROADS.map(e => ({c:e[0] === 20 ? 12 : e[0], mall:e[0] === 20, p:decode(e.slice(1), 1)}));
    for (const b of BLD) oPoly(offsetPoly(b.P, b.st === 'shed' ? 1 : 3), 1);
    for (const r of ROADS) oLine(r.p, r.c <= 6 ? 10 : r.c <= 8 ? 8 : r.c === 10 ? 5.5 : r.c === 11 ? 3.6 : 1.6, r.c === 12 ? 4 : 2);
