    { const [qx, qz, deg] = QD_FRAME, F = rotP2(qx, qz, -deg*PI/180); oPoly(rectP(F, -144, 143, -125, 134), 1); oPoly(rectP(F, -150, 150, -178, -125), 7); }
    paintGround();
    M.veg.c('#5f9a45', 0.04); drapeV(M.veg, OVAL, 0.14, 16);
    quad();
    for (const b of BLD){ try { if (b.sig && SIGF[b.sig]) SIGF[b.sig](b); else building(b); } catch (e){ console.error('stanford building ' + b.i, e); } }
    const nsa = seqArcades(); track(); frost(); claw();
    const np = palmDrive(), nt = plantTrees(), nl = streetLights();
    for (const k of Object.keys(M)) flushV(g, M[k]);
    const st = {ms:Math.round(performance.now() - t0), tris:STATS.tris, meshes:STATS.calls, bld:BLD.length, palms:np, trees:nt, lights:nl, seqArc:nsa};
